// Check source freshness; the native schema description is regenerated by the
// documented SQLX_OFFLINE=false command, and the real-store suite executes it.
import { readFile, readdir } from "node:fs/promises";
import { createHash } from "node:crypto";
import assert from "node:assert/strict";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

const root = fileURLToPath(new URL("../../crates/durable-steps/", import.meta.url));
const expected = new Set();
for (const directory of ["queries", "tests/conformance/queries"]) {
  for (const name of await readdir(join(root, directory))) {
    if (!name.endsWith(".sql")) continue;
    const sql = await readFile(join(root, directory, name), "utf8");
    const hash = createHash("sha256").update(sql).digest("hex");
    const filename = `query-${hash}.json`;
    const metadata = JSON.parse(await readFile(join(root, ".sqlx", filename), "utf8"));
    assert.equal(metadata.query, sql);
    assert.equal(metadata.db_name, "Turso");
    assert.equal(metadata.hash, hash);
    expected.add(filename);
  }
}
const actual = (await readdir(join(root, ".sqlx"))).filter(name => name.endsWith(".json"));
assert.deepEqual(new Set(actual), expected, "remove obsolete metadata after regeneration");
console.log(`${expected.size} checked-query metadata files match current SQL sources`);
